// 3 days/week, ~45 min sessions, moderate intensity. Equipment: Dumbbells & bench.
# Week 1
// Estimated ~41 min
## Full Body A
// Hold the dumbbell at your chest, elbows inside knees.
Goblet Squat, Dumbbell / 3x8 / 12kg / 120s / progress: dp(2kg, 8, 12)
// Bench at ~30°, press up and slightly back.
Incline Bench Press, Dumbbell / 3x8 / 8kg / 120s / progress: dp(2kg, 8, 12)
// Hand on the bench, pull the dumbbell to your hip.
Bent Over One Arm Row, Dumbbell / 3x8 / 12kg / 120s / progress: dp(2kg, 8, 12)
// Low back pressed into the floor, extend opposite arm and leg.
Dead Bug, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Elbows pinned to your sides, no swinging.
Bicep Curl, Dumbbell / 3x10 / 6kg / 75s / warmup: none / progress: dp(2kg, 10, 14)

// Estimated ~42 min
## Full Body B
// Soft knees, slide dumbbells down your thighs, hips back.
Romanian Deadlift, Dumbbell / 3x8 / 10kg / 120s / progress: dp(2kg, 8, 12)
// Seated or standing, press up without arching your back.
Shoulder Press, Dumbbell / 3x8 / 8kg / 120s / progress: dp(2kg, 8, 12)
// Step back, front shin vertical, push through the front heel.
Reverse Lunge, Dumbbell / 3x10 / 6kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// One dumbbell overhead with both hands, lower behind your head.
Triceps Extension, Dumbbell / 3x10 / 6kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// Hinge forward, raise arms out wide with soft elbows.
Reverse Fly, Dumbbell / 3x10 / 4kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// Curl ribs toward hips, don't pull on your neck.
Crunch, Bodyweight / 3x8 / 0kg / 75s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}

// Estimated ~41 min
## Full Body C
// Hold the dumbbell at your chest, elbows inside knees.
Goblet Squat, Dumbbell / 3x8 / 12kg / 120s
// Lower with control until elbows are just below the bench.
Bench Press, Dumbbell / 3x8 / 10kg / 120s / progress: dp(2kg, 8, 12)
// Chest on an incline bench, row elbows back.
Chest-Supported Row, Dumbbell / 3x8 / 10kg / 120s / progress: dp(2kg, 8, 12)
// Dumbbell on hips, drive up through heels.
Glute Bridge, Dumbbell / 3x10 / 12kg / 75s / warmup: none / progress: dp(2kg, 10, 14)
// Curl ribs toward hips, don't pull on your neck.
Crunch, Bodyweight / 3x8 / 0kg / 75s / warmup: none
